import { setTimeout as sleep } from 'node:timers/promises';
import { HEARTBEAT_KEY, MAX_ATTEMPTS, inTransaction, openDatabase, type JobRow } from './db.ts';

/** Duration of one processing step. */
const STEP_MS = 100;
/** How often an idle worker checks the queue. */
const IDLE_POLL_MS = 200;
/** How often the worker writes its heartbeat. */
const BEAT_EVERY_MS = 1_000;
/** Retry back-off bounds for a failed attempt. */
const RETRY_MIN_MS = 250;
const RETRY_MAX_MS = 2_000;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const nowIso = (): string => new Date().toISOString();

let lastBeat = 0;
function heartbeat(force = false): void {
  const now = Date.now();
  if (!force && now - lastBeat < BEAT_EVERY_MS) return;
  lastBeat = now;
  db.prepare('INSERT INTO meta (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value').run(HEARTBEAT_KEY, String(now));
}

/**
 * Jobs left `running` by a worker that died are queued again. The interrupted attempt has already
 * been counted, so it stays counted, except when it was the last allowed attempt: then it is re-run
 * as that same attempt so the total never exceeds MAX_ATTEMPTS.
 */
function recoverInterrupted(): void {
  db.prepare(
    `UPDATE jobs
        SET status = 'queued',
            completed = 0,
            attempts = CASE WHEN attempts >= ? THEN attempts - 1 ELSE attempts END,
            run_after = 0,
            updated_at = ?
      WHERE status = 'running'`,
  ).run(MAX_ATTEMPTS, nowIso());
}

function claimNext(): JobRow | undefined {
  return inTransaction(db, () => {
    const next = db
      .prepare(`SELECT seq FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1`)
      .get(Date.now()) as { seq: number } | undefined;
    if (!next) return undefined;
    db.prepare(`UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE seq = ?`).run(nowIso(), next.seq);
    return db.prepare('SELECT * FROM jobs WHERE seq = ?').get(next.seq) as unknown as JobRow;
  });
}

async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;
  await sleep(STEP_MS);
  if (stopping) return; // left `running`; recovered on the next start

  if (attempt <= job.fail_attempts) {
    if (attempt >= MAX_ATTEMPTS) {
      db.prepare(
        `UPDATE jobs SET status = 'failed', completed = 0, result_output = NULL, error = 'transient failure', updated_at = ? WHERE seq = ?`,
      ).run(nowIso(), job.seq);
    } else {
      const delay = RETRY_MIN_MS + Math.floor(Math.random() * (RETRY_MAX_MS - RETRY_MIN_MS));
      db.prepare(`UPDATE jobs SET status = 'queued', completed = 0, run_after = ?, updated_at = ? WHERE seq = ?`).run(
        Date.now() + delay,
        nowIso(),
        job.seq,
      );
    }
    return;
  }

  for (let done = 1; done <= job.steps; done++) {
    await sleep(STEP_MS);
    if (stopping) return;
    db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ?').run(done, nowIso(), job.seq);
    heartbeat();
  }
  db.prepare(
    `UPDATE jobs SET status = 'completed', completed = ?, result_output = ?, error = NULL, updated_at = ? WHERE seq = ?`,
  ).run(job.steps, job.input.toUpperCase(), nowIso(), job.seq);
}

recoverInterrupted();
heartbeat(true);
console.log('worker started');

while (!stopping) {
  heartbeat();
  const job = claimNext();
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  await runAttempt(job);
}

db.prepare('UPDATE meta SET value = ? WHERE key = ?').run('0', HEARTBEAT_KEY);
db.close();
process.exit(0);

