import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { HEARTBEAT_KEY, inTransaction, openDatabase, toJob, type JobRow } from './db.ts';

/** The worker counts as up only if its heartbeat is at most this old. */
const HEARTBEAT_FRESH_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

interface FieldError {
  field: string;
  message: string;
}

interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function invalid(res: ServerResponse, fields: FieldError[]): void {
  const summary = fields.map((f) => `${f.field}: ${f.message}`).join('; ');
  sendError(res, 400, 'invalid_request', `Invalid request: ${summary}`, fields);
}

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

/** Validates the parsed request body. Returns either the submission or every offending field. */
function validateSubmission(raw: unknown): { ok: true; value: Submission } | { ok: false; fields: FieldError[] } {
  if (!isObject(raw)) return { ok: false, fields: [{ field: 'body', message: 'body must be a JSON object' }] };
  const fields: FieldError[] = [];

  for (const key of Object.keys(raw)) {
    if (!KNOWN_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  if (raw.input === undefined) {
    fields.push({ field: 'input', message: 'input is required' });
  } else if (typeof raw.input !== 'string') {
    fields.push({ field: 'input', message: 'input must be a string' });
  } else if (raw.input.length < 1 || raw.input.length > 1000) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
  } else if (raw.input.trim() === '') {
    fields.push({ field: 'input', message: 'input must not be only whitespace' });
  } else {
    input = raw.input;
  }

  const steps = integerField(raw, 'steps', 1, 20, 5, fields);
  const failAttempts = integerField(raw, 'failAttempts', 0, 5, 0, fields);

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

function integerField(raw: Record<string, unknown>, name: string, min: number, max: number, fallback: number, fields: FieldError[]): number {
  if (!(name in raw)) return fallback;
  const value = raw[name];
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
    return fallback;
  }
  if (value < min || value > max) {
    fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return value;
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function isJsonContentType(header: string | undefined): boolean {
  if (!header) return false;
  return (header.split(';')[0] ?? '').trim().toLowerCase() === 'application/json';
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];

  const keyHeader = req.headers['idempotency-key'];
  let key: string | null = null;
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && IDEMPOTENCY_KEY_RE.test(keyHeader)) key = keyHeader;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const text = await readBody(req);
  let submission: Submission | undefined;
  if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (text === null) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(text);
    } catch {
      fields.push({ field: 'body', message: 'body must be valid JSON' });
    }
    if (parsed !== undefined || text.trim() === 'null') {
      if (!(parsed === undefined)) {
        const v = validateSubmission(parsed);
        if (v.ok) submission = v.value;
        else fields.push(...v.fields);
      }
    }
  }

  if (fields.length > 0 || submission === undefined) {
    if (fields.length === 0) fields.push({ field: 'body', message: 'body is required' });
    return invalid(res, fields);
  }

  const payload = submission;
  const outcome = inTransaction(db, (): { status: number; row: JobRow } | 'conflict' => {
    if (key !== null) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
      if (existing) {
        const same = existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts;
        return same ? { status: 200, row: existing } : 'conflict';
      }
    }
    const now = new Date().toISOString();
    const id = randomUUID();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
    ).run(id, payload.input, payload.steps, payload.failAttempts, key, now, now);
    const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow;
    return { status: 201, row };
  });

  if (outcome === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.status, toJob(outcome.row));
}

function listJobs(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(toJob) });
}

function getJob(res: ServerResponse, id: string): void {
  const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
  if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
  send(res, 200, toJob(row));
}

function health(res: ServerResponse): void {
  const row = db.prepare('SELECT value FROM meta WHERE key = ?').get(HEARTBEAT_KEY) as { value: string } | undefined;
  const alive = row !== undefined && Date.now() - Number(row.value) < HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: alive ? 'up' : 'down' });
}

type Handler = () => void | Promise<void>;

function routesFor(req: IncomingMessage, res: ServerResponse, path: string): Map<string, Handler> | undefined {
  if (path === '/health') return new Map([['GET', () => health(res)]]);
  if (path === '/') {
    return new Map([['GET', () => {
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(uiHtml);
    }]]);
  }
  if (path === '/api/jobs') {
    return new Map<string, Handler>([
      ['GET', () => listJobs(res)],
      ['POST', () => createJob(req, res)],
    ]);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (match) {
    let id: string;
    try {
      id = decodeURIComponent(match[1] ?? '');
    } catch {
      return undefined;
    }
    return new Map([['GET', () => getJob(res, id)]]);
  }
  return undefined;
}

const server = createServer((req, res) => {
  const path = new URL(req.url ?? '/', 'http://localhost').pathname;
  const routes = routesFor(req, res, path);
  if (!routes) return sendError(res, 404, 'not_found', 'Not found.');
  const handler = routes.get(req.method ?? 'GET');
  if (!handler) return sendError(res, 405, 'method_not_allowed', `Method ${req.method} is not allowed here.`);
  Promise.resolve(handler()).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let stopping = false;
function shutdown(): void {
  if (stopping) return;
  stopping = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => process.exit(0), 3_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

